svg.script:

(function() {
  var root = document.getElementById('a12p16h-svg');
  if (!root) return;

  var modesData = {
    wall: {
      title: "M. Obturador Interno",
      tagText: "PAREDE LATERAL (NÃO É CHÃO)",
      tagClass: "a12p16h-badge-wall",
      alertHeader: "ARMADILHA DE PROVA DA RESIDÊNCIA",
      alertBg: "#3f121d",
      alertBorder: "#991b1b",
      alertText: "O <strong>músculo obturador interno</strong> é volumoso e fica dentro da pelve, mas <em>forra a parede óssea lateral</em>! Ele NUNCA compõe o diafragma pélvico (chão). Confundi-lo com o levantador do ânus é o erro nº 1 nas questões de anatomia pélvica.",
      summaryText: "• <strong>Parede Lateral:</strong> M. Obturador Interno.<br/>• <strong>Função:</strong> Rotação lateral do quadril.<br/>• <strong>Regra:</strong> Forra a pelve, mas NÃO sustenta as vísceras de baixo."
    },
    floor: {
      title: "M. Levantador do Ânus",
      tagText: "CHÃO PÉLVICO (DIAFRAGMA)",
      tagClass: "a12p16h-badge-floor",
      alertHeader: "COMPOSIÇÃO DO DIAFRAGMA PÉLVICO",
      alertBg: "#3b112c",
      alertBorder: "#ec4899",
      alertText: "O verdadeiro <strong>chão pélvico</strong> é formado pelo <em>M. Levantador do Ânus</em> (pubococcígeo, iliococcígeo e puborretal) + <em>M. Coccígeo</em>. Eles formam um funil muscular suspenso que suporta todo o peso visceral.",
      summaryText: "• <strong>Componentes:</strong> Pubococcígeo + Iliococcígeo + Puborretal.<br/>• <strong>Fixação:</strong> Origina-se no ATLA (parede lateral) e converge para a linha média."
    },
    atla: {
      title: "Arco Tendíneo (ATLA)",
      tagText: "TRANSIÇÃO FASCIAL DE ORIGEM",
      tagClass: "a12p16h-badge-atla",
      alertHeader: "PONTO DE TRANSIÇÃO ANATÔMICA",
      alertBg: "#3a2507",
      alertBorder: "#fbbf24",
      alertText: "O <strong>Arco Tendíneo do Levantador do Ânus (ATLA)</strong> é um espessamento da fáscia do m. obturador interno. É exatamente no ATLA que o levantador do ânus se origina, marcando a transição exata entre a <em>parede lateral</em> e o <em>chão</em>.",
      summaryText: "• <strong>Localização:</strong> Suspenso sobre a fáscia do obturador interno.<br/>• <strong>Importância:</strong> Ponto de ancoragem cirúrgica e marco anatômico decisivo."
    },
    kegel: {
      title: "Feixe Pubococcígeo",
      tagText: "ALVO DE FORTALECIMENTO (KEGEL)",
      tagClass: "a12p16h-badge-kegel",
      alertHeader: "CORRELAÇÃO CLÍNICA DE FISIOTERAPIA",
      alertBg: "#06372b",
      alertBorder: "#34d399",
      alertText: "Dentro do levantador do ânus, o <strong>músculo pubococcígeo</strong> é o feixe muscular diretamente fortalecido nos <em>Exercícios de Kegel</em> e biofeedback. Ele envolve os hiatos urogenital e anal, garantindo a continência.",
      summaryText: "• <strong>Indicação:</strong> Tratamento da incontinência urinária de esforço.<br/>• <strong>Mecanismo:</strong> Aumento do tónus muscular e fechamento uretral sob estresse."
    }
  };

  function setMode(mode) {
    if (!modesData[mode]) return;
    root.setAttribute('data-active-mode', mode);

    // Update tabs active state
    var tabs = ['wall', 'floor', 'atla', 'kegel'];
    tabs.forEach(function(m) {
      var tabEl = document.getElementById('a12p16h-tab-' + m);
      if (tabEl) {
        if (m === mode) {
          tabEl.classList.add('a12p16h-active');
        } else {
          tabEl.classList.remove('a12p16h-active');
        }
      }
    });

    // Update panel contents
    var data = modesData[mode];
    var titleEl = document.getElementById('a12p16h-panel-title');
    var tagTextEl = document.getElementById('a12p16h-panel-tag-text');
    var tagBgEl = document.getElementById('a12p16h-panel-tag-bg');
    var alertHeaderEl = document.getElementById('a12p16h-alert-header');
    var alertBoxEl = document.getElementById('a12p16h-alert-box');
    var alertTextEl = document.getElementById('a12p16h-alert-text');
    var summaryTextEl = document.getElementById('a12p16h-summary-text');

    if (titleEl) titleEl.textContent = data.title;
    if (tagTextEl) tagTextEl.textContent = data.tagText;
    if (tagBgEl) tagBgEl.setAttribute('class', data.tagClass);
    if (alertHeaderEl) alertHeaderEl.textContent = data.alertHeader;
    if (alertBoxEl) {
      alertBoxEl.style.fill = data.alertBg;
      alertBoxEl.style.stroke = data.alertBorder;
    }
    if (alertTextEl) alertTextEl.innerHTML = data.alertText;
    if (summaryTextEl) summaryTextEl.innerHTML = data.summaryText;
  }

  // Attach click events to tabs
  ['wall', 'floor', 'atla', 'kegel'].forEach(function(m) {
    var tabEl = document.getElementById('a12p16h-tab-' + m);
    if (tabEl) {
      tabEl.addEventListener('click', function() { setMode(m); });
    }
  });

  // Attach click events to anatomical groups and labels
  var bindings = [
    { id: 'a12p16h-group-wall', mode: 'wall' },
    { id: 'a12p16h-lbl-wall', mode: 'wall' },
    { id: 'a12p16h-group-floor', mode: 'floor' },
    { id: 'a12p16h-lbl-floor', mode: 'floor' },
    { id: 'a12p16h-group-atla', mode: 'atla' },
    { id: 'a12p16h-lbl-atla', mode: 'atla' },
    { id: 'a12p16h-group-kegel', mode: 'kegel' },
    { id: 'a12p16h-lbl-kegel', mode: 'kegel' }
  ];

  bindings.forEach(function(item) {
    var el = document.getElementById(item.id);
    if (el) {
      el.addEventListener('click', function() { setMode(item.mode); });
    }
  });
})();
